import InventoryIcon from '@mui/icons-material/Inventory';
import DeleteIcon from '@mui/icons-material/Delete';
import { Box, Tooltip } from '@mui/material';
import { alpha } from '@mui/material/styles';
import { ColumnDef } from '@tanstack/react-table';
import React from 'react';
import { useTranslation } from 'react-i18next';

import { IInventoryDetailsData } from '../../core/Interface/inventory.interface';
import { Privileges } from '../../core/types/commonType';
import useUser from '../../core/hooks/useUser';
import { getPriceFormat } from '../../core/utils';

const ActionBtn = ({
  color,
  children,
  onClick,
  show = true,
  title,
}: {
  color: string;
  children: React.ReactNode;
  onClick: () => void;
  show?: boolean;
  title: string;
}) => {
  if (!show) return null;
  return (
    <Tooltip arrow title={title}>
      <Box
        onClick={(event) => {
          event.stopPropagation();
          onClick();
        }}
        sx={{
          alignItems: 'center',
          background: alpha(color, 0.1),
          border: `1px solid ${alpha(color, 0.22)}`,
          borderRadius: '7px',
          color,
          cursor: 'pointer',
          display: 'flex',
          height: 30,
          justifyContent: 'center',
          transition: 'all 0.15s',
          width: 30,
          '&:hover': {
            background: color,
            color: '#fff',
            transform: 'scale(1.07)',
          },
        }}
      >
        {children}
      </Box>
    </Tooltip>
  );
};

const useInventoryDetailsColumn = (
  currencyCode: string,
  handleOpenStockAdjust: (product: IInventoryDetailsData) => void,
  handleDelete: (product: IInventoryDetailsData) => void
) => {
  const { t } = useTranslation(['inventory', 'product']);
  const { userHasRight } = useUser();

  return [
    {
      accessorKey: 'sn',
      header: '#',
      size: 50,
    },
    {
      accessorKey: 'code',
      header: t('inventory:code'),
      size: 150,
    },
    {
      accessorKey: 'name',
      header: t('inventory:productName'),
      size: 200,
    },
    {
      accessorKey: 'categoryCode',
      header: t('inventory:categoryCode'),
      size: 160,
    },
    {
      accessorKey: 'categoryName',
      header: t('inventory:categoryName'),
      size: 160,
    },
    {
      accessorKey: 'soldInOneMonth',
      header: t('inventory:soldInOneMonth'),
      size: 60,
      cell: (cell) => (
        <Box
          sx={{  
            textAlign: 'center',
          }}
        >
          {cell.row.original.soldInOneMonth}
        </Box>
      ),
    },
    {
      accessorKey: 'stockAvailable',
      header: () => (
        <Box sx={{ textAlign: 'center' }}>
          {t('inventory:stockAvailable')}
        </Box>
      ),
      size: 100,
      cell: (cell) => {
        const stock = cell.row.original.stockAvailable;
        const isLow = stock <= 5;
        return (
          <Box sx={{ display: 'flex', justifyContent: 'center' }}>
            <Box
              sx={{
                background: isLow
                  ? alpha('#DC2626', 0.1)
                  : alpha('#22C55E', 0.1),
                border: `1px solid ${
                  isLow ? alpha('#DC2626', 0.25) : alpha('#22C55E', 0.25)
                }`,
                borderRadius: '20px',
                color: isLow ? '#b91c1c' : '#15803d',
                fontSize: 12,
                fontWeight: 700,
                minWidth: 40,
                px: 1.25,
                py: 0.25,
                textAlign: 'center',
              }}
            >
              {stock}
            </Box>
          </Box>
        );
      },
    },
    {
      accessorKey: 'unitPrice',
      header: () => (
        <Box sx={{ textAlign: 'right' }}>
          {t('inventory:unitPrice')}
        </Box>
      ),
      size: 160,
      cell: (cell) => (
        <Box
          sx={{
            color: '#2563EB',
            fontWeight: 700,
            textAlign: 'right',
          }}
        >
          {getPriceFormat(cell.row.original.unitPrice, currencyCode)}
        </Box>
      ),
    },
    {
      accessorKey: 'action',
      header: '',
      size: 90,
      cell: (cell) => {
        const data = cell.row.original;
        return (
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 0.75, justifyContent: 'flex-end' }}>
            <ActionBtn
              color="#D97706"
              onClick={() => handleOpenStockAdjust(data)}
              show={userHasRight(Privileges.StockAdjustment)}
              title="Stock Adjustment"
            >
              <InventoryIcon
                sx={{ color: '#D97706', fontSize: 16 }}
              />
            </ActionBtn>
            <ActionBtn
              color="#DC2626"
              onClick={() => handleDelete(data)}
              show={userHasRight(Privileges.ProductDDelete)}
              title={t('product:deleteProduct')}
            >
              <DeleteIcon sx={{ fontSize: 16 }} />
            </ActionBtn>
          </Box>
        );
      },
    },
    {
      accessorKey: 'id',
    },
  ] as ColumnDef<IInventoryDetailsData>[];
};

export default useInventoryDetailsColumn;
